INSERT OR REPLACE INTO sqtrack_items (code, part_no, phase, seq, title, detail, evidence_pages, severity, team, form_code, sq_item_code, tag) VALUES
  -- phase 1 서류확보
  ('25460-2T500:1-01', '25460-2T500', 1, 1, '관리계획서 최신본 준비·정독', '심사 시작점. 2권 p058~062(18공정, 특별특성 ◆=로브레이징 조건·L/TEST 기밀 3kg/cm2). 개정이력 3건이 도면 EO와 정합함을 즉답 가능하게.', '2권 p058~062', 'orange', 'pumjil', 'J1102-03', NULL, '관리계획서'),
  ('25460-2T500:1-02', '25460-2T500', 1, 2, '제출문서 목록 26종 O/X 대조·결번 확인', '목록표(p002)의 O 항목 실물 존재 확인. X 항목(공정능력 평가결과)은 소명 시나리오 준비.', '2권 p002', 'orange', 'pumjil', NULL, NULL, '서류준비'),
  ('25460-2T500:1-03', '25460-2T500', 1, 3, '특별특성 기호 대조표 편철', '협정서 C 등급 vs 관리계획서·FMEA ◆ 기호 혼용 — 대조표 1장 없으면 정합성 질문 확정.', '2권 p005 vs p061', 'orange', 'pumjil', 'J1100-03', NULL, '특별특성'),
  -- phase 2 정합성 리스크 해소
  ('25460-2T500:2-01', '25460-2T500', 2, 1, 'SQ 인증서 만료본 교체(2023.11.30 만료)', '세트에 만료된 용접 G등급 인증서(WD707) 편철 — 갱신본 확보·교체. 심사 전 필수.', '2권 p070', 'red', 'pumjil', NULL, NULL, '인증서'),
  ('25460-2T500:2-02', '25460-2T500', 2, 2, '공정능력(CP/CPK) 미제출 해소', '제출목록에 X 명기 + CP에 CPK 관리항목 자체가 없음. 6월 IATF 라이브 심사 지적과 동일 계열 — 기밀시험 등 특별특성 공정 공정능력 기록 체계 구축(전사 최우선).', '2권 p002', 'red', 'pumjil', 'L4102-02', NULL, '공정능력'),
  ('25460-2T500:2-03', '25460-2T500', 2, 3, '초도품보증서 수요자 판정·승인번호 회수', '수요자 종합판정·승인번호·처리일자 공란(서명만 존재). 1차사 통해 승인 완결 회수 — 28236 완결본을 선례로 제시.', '2권 p003', 'red', 'pumjil', NULL, NULL, 'PSW'),
  ('25460-2T500:2-04', '25460-2T500', 2, 4, '검사협정서 체결일·미국 안전부품 체크 기입', '체결일 공란 + 해당/해당무 미체크 상태.', '2권 p004', 'orange', 'pumjil', NULL, NULL, '협정서'),
  ('25460-2T500:2-05', '25460-2T500', 2, 5, 'Mahr 형상측정 날짜 역전·서명 공란 정리', '측정일(5/11~12)이 제출일(5/10)보다 늦고 검사자 서명 전부 공란, p017에 NG로 읽히는 수기 주석 — 재발행 또는 소명.', '2권 p013~019', 'orange', 'pumjil', NULL, NULL, '성적서'),
  ('25460-2T500:2-06', '25460-2T500', 2, 6, 'FMEA 품명 오기·오타 정정', '품명이 PIPE HOSE ASSY-HEATER로 오기(정: WATER OUTLET), LEAK TSET 오타.', '2권 p063~064', 'yellow', 'gaebal', 'J1101-01', NULL, 'FMEA'),
  ('25460-2T500:2-07', '25460-2T500', 2, 7, 'CP 시작단계→양산단계 전환 검토', '양산 3년차인데 CP가 시작단계(초도) 체크 상태 — 심사원 질문 예상.', '2권 p058', 'orange', 'gaebal', NULL, NULL, '관리계획서'),
  ('25460-2T500:2-08', '25460-2T500', 2, 8, '기밀시험 압력 표기 불일치 정리(3↔5kg/cm2)', '갑지·종합표 3kg/cm2 vs 성적서 5kgf/cm2 — 규격 기준 확인 후 표기 통일 또는 소명.', '1권 p001·p003 vs p005', 'orange', 'pumjil', NULL, NULL, '성적서'),
  ('25460-2T500:2-09', '25460-2T500', 2, 9, 'MDS 명의·단위 정리(Il-Shin Precision, 서브ASSY)', 'IMDS가 타사 명의 + 서브ASSY(25461) 단위 — 당사 계정 이관 및 완성품 단위 정리.', '2권 p045~049', 'red', 'gaebal', NULL, NULL, 'IMDS'),
  -- phase 3 현장검증
  ('25460-2T500:3-01', '25460-2T500', 3, 1, 'LEAK 마스터(OK/NG) 정비 + NG 검출 시연 리허설', 'CP: 마스터검사 시업전. 시편 식별라벨·보관대·검출확인 기록 정비, 심사원 앞 NG 시연 대비.', 'CP p059~062 (K7)', 'red', 'saengsan', 'L2300-01', NULL, 'LEAK 원점'),
  ('25460-2T500:3-02', '25460-2T500', 3, 2, '스포트 팁 카운터↔관리대장 정합(연마 50,000타)', '카운터 현재값과 대장 기록 일치 확인. 28236(5,000/20,000EA)과 기준 상이 사유도 준비.', 'CP p059 (K8)', 'orange', 'saengsan', 'M1200-08', NULL, '팁주기'),
  ('25460-2T500:3-03', '25460-2T500', 3, 3, '브레이징 조건관리 LIST↔현행 ITEM + 계측기 교정', '3-zone 온도(700~850/1,065~1,100)·LPG/AIR 유량 — 컨트롤박스 표시값이 CP 범위인지, 온도계·게이지 교정라벨.', 'CP p060 (K6)', 'orange', 'saengsan', NULL, NULL, '브레이징 조건'),
  ('25460-2T500:3-04', '25460-2T500', 3, 4, '설비일상점검표·자주검사 C/SHEET 3개월 연속성', '결측일·서명 누락 점검 — 소급 기입 금지, 지금부터 연속 축적.', 'CP 전 공정 (K4·K5)', 'red', 'saengsan', 'L1100-07', NULL, '일상점검'),
  ('25460-2T500:3-05', '25460-2T500', 3, 5, 'C/SHEET↔MES 수량 정합 + 입력 시점 통일', '자주검사 기록과 MES 실적 수량 일치 사전 점검, 작업자별 입력 시점 통일.', '(K10)', 'orange', 'saengsan', NULL, NULL, '자주검사·MES'),
  ('25460-2T500:3-06', '25460-2T500', 3, 6, '알곤 가접 실시 여부 확정(전 품번 공통)', '4품번 CP 어디에도 알곤 가접 없음 — 현장에서 실시 중이면 CP=현장 불일치(중대). 실시 확인 시 CP 등재+토치 드레싱 주기 기준 신설.', 'CP 4종 부재', 'red', 'saengsan', NULL, NULL, '알곤가접'),
  -- phase 4 인터뷰
  ('25460-2T500:4-01', '25460-2T500', 4, 1, '용접·브레이징 작업자 인터뷰 리허설', '팁 몇 타에 연마/교체? 카운터 어디? 온도 이탈 시 조치? 동링 누락 발견 방법? 절단 용입 누가 언제?', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, '용접·브레이징'),
  ('25460-2T500:4-02', '25460-2T500', 4, 2, 'LEAK 작업자 인터뷰 리허설', '마스터 언제 돌리나? NG마스터가 OK 뜨면? 압력·시간 설정 변경 권한은?', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, 'LEAK 원점'),
  ('25460-2T500:4-03', '25460-2T500', 4, 3, '수입검사 담당 인터뷰 리허설', 'LOT당 몇 개? 성적서 없으면 입고되나? 불합격 통보 경로(가공업체·구매)?', '추적맵 §3', 'orange', 'pumjil', 'L2100-07', NULL, '수입검사'),
  ('25460-2T500:4-04', '25460-2T500', 4, 4, '자주검사·MES 인터뷰 리허설', '어느 부위를 몇 개, 언제 보고, MES에 언제 입력? 설비 점검은 아침에 뭘 보나?', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, '자주검사·MES');

-- ── 28236-2MAA0 ──────────────────────────────────────────────
INSERT OR REPLACE INTO sqtrack_items (code, part_no, phase, seq, title, detail, evidence_pages, severity, team, form_code, sq_item_code, tag) VALUES
  ('28236-2MAA0:1-01', '28236-2MAA0', 1, 1, '관리계획서 최신본 준비·정독', '2권 p046~050(12공정, ◆3=브레이징 냉각 25~45도·LEAK 압력 5Kg/cm2 x2). 개정 3건(b=25.08.21 치수정정) 정합 즉답 준비.', '2권 p046~050', 'orange', 'pumjil', 'J1102-03', NULL, '관리계획서'),
  ('28236-2MAA0:1-02', '28236-2MAA0', 1, 2, '제출문서 목록 26종 O/X 대조·결번 확인', '목록 X 4건의 사유 정리. 조직도는 X인데 실물 첨부(p059) — 목록 갱신.', '2권 p002', 'orange', 'pumjil', NULL, NULL, '서류준비'),
  ('28236-2MAA0:1-03', '28236-2MAA0', 1, 3, 'EO 표기 정리(C2MRE654/C2MSE481/C2MRE604)', '1권 갑지=C2MRE654, 2권 사유서=C2MSE481(변경전 C2MRE604 판독) — 관리대장·파일명 정리 및 즉답 준비.', '1권 p001 · 2권 p001', 'yellow', 'pumjil', NULL, NULL, '서류준비'),
  ('28236-2MAA0:2-01', '28236-2MAA0', 2, 1, 'IMDS 명의 이관(Il-Shin Precision→당사)', '공급업체 명의가 타사 계정 — 이관 후 재제출. 리드타임 김, 조기 착수.', '2권 p038~042', 'red', 'gaebal', NULL, NULL, 'IMDS'),
  ('28236-2MAA0:2-02', '28236-2MAA0', 2, 2, 'CP의 SPC 선언 대비 기밀 관리도 구축', 'CP 70/90공정에 SPC 적용(Cp·Cpk 산출, 관리도 활용) 명시 — 실물 관리도 부재가 최대 급소. 치수 Cp/Cpk 3건은 편철됨.', '2권 p047~050 vs p056~058', 'red', 'pumjil', 'L4102-02', NULL, '공정능력'),
  ('28236-2MAA0:2-03', '28236-2MAA0', 2, 3, 'FMEA b개정(25.08.21) 동기화', 'CP·기준서·협정서는 3개정인데 FMEA만 2개정 — 치수정정이 FMEA 비영향임을 소명하거나 개정 동기화.', '2권 p051', 'orange', 'gaebal', 'J1101-01', NULL, 'FMEA'),
  ('28236-2MAA0:2-04', '28236-2MAA0', 2, 4, '공정능력 성적서 규격상한 오기 정정', '내경 12.1+0.3의 상한이 12.30으로 기재(정: 12.40) — Cpk 1.32는 보수적 산출이나 오기 정정 필요.', '2권 p058', 'yellow', 'pumjil', 'L4102-02', NULL, '공정능력'),
  ('28236-2MAA0:2-05', '28236-2MAA0', 2, 5, '밀시트 제3사 명의 추적성 소명 패키지', '밀시트 고객명 세종에스피, SWCH10A 증명 엔디에프, SGS 명의 대호특수강 — 구매경로 체인 다이어그램 + Heat No-LOT 연결 시연 준비.', '2권 p015·p024·p025', 'orange', 'gumae', NULL, NULL, '추적성'),
  ('28236-2MAA0:2-06', '28236-2MAA0', 2, 6, '신뢰성 종합 결재 자필서명 보완', '성명 인쇄만 있고 수기 서명 없음 + 작성일 부재 — 규칙화.', '2권 p010', 'yellow', 'pumjil', NULL, NULL, '성적서'),
  ('28236-2MAA0:2-07', '28236-2MAA0', 2, 7, '치수 증빙 범위 확인(1권 을지 부재)', '1권 갑지 승인항목 치수 체크인데 치수 데이터 전무 — 정기검사 치수 증빙 위치 확인·보완.', '1권 p001', 'orange', 'pumjil', NULL, NULL, '성적서'),
  ('28236-2MAA0:3-01', '28236-2MAA0', 3, 1, 'LEAK 마스터(OK/NG) 정비 + NG 검출 시연(1차·2차)', 'CP: 시업전 마스터 + SPC. 70·90 두 공정 모두 대상.', 'CP p047~050 (K7)', 'red', 'saengsan', 'L2300-01', NULL, 'LEAK 원점'),
  ('28236-2MAA0:3-02', '28236-2MAA0', 3, 2, '팁 카운터↔관리대장 정합(연마 5,000·교체 20,000EA)', 'CP에 카운터 명시 — 현재값·교체이력 연속성. 심사원 단골 확인 지점.', 'CP p047 (K8)', 'orange', 'saengsan', 'M1200-08', NULL, '팁주기'),
  ('28236-2MAA0:3-03', '28236-2MAA0', 3, 3, '브레이징 냉각 ZONE(특별특성) 온도 기록 확인', '냉각 25~45도가 ◆ — 왜 특별특성인지(급랭 균열 방지) 작업자 즉답 훈련 포함.', 'CP p048 (K6)', 'orange', 'saengsan', NULL, NULL, '브레이징 조건'),
  ('28236-2MAA0:3-04', '28236-2MAA0', 3, 4, '설비일상점검표·자주검사 C/SHEET 3개월 연속성', '초/중/종품 실측 기입 여부(O표시만이면 지적).', 'CP 전 공정 (K4·K5)', 'red', 'saengsan', 'L1100-07', NULL, '일상점검'),
  ('28236-2MAA0:3-05', '28236-2MAA0', 3, 5, 'C/SHEET↔MES 수량 정합 + 조도계 등 계측기 확인', '수입검사에 조도 12.5RT 요구 — 조도계 보유·교정 확인 포함.', '(K10·K11)', 'orange', 'saengsan', NULL, NULL, '자주검사·MES'),
  ('28236-2MAA0:4-01', '28236-2MAA0', 4, 1, '용접·브레이징 작업자 인터뷰 리허설', '팁 5천/2만 기준 즉답 + 냉각온도 특별특성 사유.', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, '용접·브레이징'),
  ('28236-2MAA0:4-02', '28236-2MAA0', 4, 2, 'LEAK 작업자 인터뷰 리허설(SPC 질문 포함)', '관리도는 누가 언제 그리나? 관리이탈이면? — CP 선언 관련 질문 대비 필수.', '추적맵 §6', 'red', 'saengsan', NULL, NULL, 'LEAK 원점'),
  ('28236-2MAA0:4-03', '28236-2MAA0', 4, 3, '수입검사 담당 인터뷰 리허설', '정밀공차(Φ12.1 +0.15)·조도 측정 방법 즉답.', '추적맵 §3', 'orange', 'pumjil', 'L2100-07', NULL, '수입검사'),
  ('28236-2MAA0:4-04', '28236-2MAA0', 4, 4, '관리자 인터뷰: 특별특성·개정·외주 즉답', '특별특성 몇 개 어디(◆3)? CP 개정 왜? 외주 ISIR·성적서 수취 체계?', '추적맵 §6', 'orange', 'pumjil', NULL, NULL, '관리자');

-- ── 28350-2M110 ──────────────────────────────────────────────
INSERT OR REPLACE INTO sqtrack_items (code, part_no, phase, seq, title, detail, evidence_pages, severity, team, form_code, sq_item_code, tag) VALUES
  ('28350-2M110:1-01', '28350-2M110', 1, 1, '관리계획서 최신본 준비·정독', '2권 p047~052(공정 10~190, ◈=브레이징 조건·LEAK 전수 0.5~0.8MPa 19초). 개정 6건(최신 C2MTE252 스티커 삭제) 정합 즉답.', '2권 p047~052', 'orange', 'pumjil', 'J1102-03', NULL, '관리계획서'),
  ('28350-2M110:1-02', '28350-2M110', 1, 2, '형제품번(2M100) 차이 답변 준비', '심사원 교차 소환 대비 — EO C2MTE252(마킹 스티커 삭제) 사양변경서로 차이 즉답.', '2권 p002', 'orange', 'pumjil', NULL, NULL, '서류준비'),
  ('28350-2M110:1-03', '28350-2M110', 1, 3, 'ISIR 표지 품질확인·결론란 공란 보완', '표지의 품질확인 4개 결과란·결론란 전부 공란.', '2권 p001', 'orange', 'pumjil', NULL, NULL, '서류준비'),
  ('28350-2M110:2-01', '28350-2M110', 2, 1, '2M100 명의 성적서 4건 혼용 편철 해소', '신뢰성 종합+첨부성적서(p037~041)가 전부 2M100 기재 — 재발행 또는 정오표+공용시험 소명서.', '2권 p037~041', 'red', 'pumjil', NULL, NULL, '품번혼용'),
  ('28350-2M110:2-02', '28350-2M110', 2, 2, '하위품번 28353 체계 소명서', 'CP 을지=28353-2M100-x vs 공급자현황·도면=28353-2M110-x — 3문서 대조 소명서 작성.', '2권 p047~052 vs p055·p057', 'red', 'pumjil', NULL, NULL, '품번혼용'),
  ('28350-2M110:2-03', '28350-2M110', 2, 3, '초도품보증서 수요자 판정 회수', '승인기준 체크 7항·종합판정·승인번호·처리일자 공란(서명만).', '2권 p003', 'red', 'pumjil', NULL, NULL, 'PSW'),
  ('28350-2M110:2-04', '28350-2M110', 2, 4, 'IMDS 미개봉 해소+중량 정합', '수신상태 미개봉(2026.05.13), 중량 226g vs 보증서 272g, 명칭 Copy_ 접두 — 재제출·승인 완료까지.', '2권 p042~046', 'red', 'gaebal', NULL, NULL, 'IMDS'),
  ('28350-2M110:2-05', '28350-2M110', 2, 5, '검사협정서 체결일·안전부품 체크 기입', '미국 안전부품 해당/해당무 미체크, 협정 체결일 공란.', '2권 p004', 'orange', 'pumjil', NULL, NULL, '협정서'),
  ('28350-2M110:2-06', '28350-2M110', 2, 6, 'CP 공정번호 140 부재 확인', '130→150 비약 — 결번인지 페이지 누락인지 원본 확인, 결번이면 차기 개정 시 정리.', '2권 p047~052', 'orange', 'gaebal', NULL, NULL, '관리계획서'),
  ('28350-2M110:2-07', '28350-2M110', 2, 7, '정기검사 치수 성적서 결권 보완(치수-1·3)', '1권에 부위 1~26·49~70 증빙 없음(치수-2·4만 존재).', '1권 p002~003', 'red', 'pumjil', NULL, NULL, '성적서'),
  ('28350-2M110:2-08', '28350-2M110', 2, 8, 'FMEA 최대 RPN(LEAK 48) 권고조치 검토', '특별특성 공정 최대 RPN에 권고조치 NONE — 임계치 기준·개선활동 근거 마련. LEAK TSET 오타 정정.', '2권 p053~054', 'yellow', 'gaebal', 'J1101-01', NULL, 'FMEA'),
  ('28350-2M110:3-01', '28350-2M110', 3, 1, 'LEAK 마스터(OK/NG) 정비 + NG 검출 시연(1회/일)', 'CP: 마스터 1회/일, 19초(가압5/평정8/검출6).', 'CP p051 (K7)', 'red', 'saengsan', 'L2300-01', NULL, 'LEAK 원점'),
  ('28350-2M110:3-02', '28350-2M110', 3, 2, '벤딩 길이센서 MASTER(짧은/긴제품) 시업전 기록', '벤딩 70/90 공정 — 마스터 시편 실물·검출 시연 + 벤딩 금형 이력카드 정비.', 'CP p049 (K7)', 'orange', 'saengsan', 'L1100-25', NULL, '벤딩 마스터·금형'),
  ('28350-2M110:3-03', '28350-2M110', 3, 3, '스포트 용접조건·냉각수 온도(18~25도) 확인', '8개소 용접 누락 검출 방법 + 조건 1회/일 기록.', 'CP p050 (K8)', 'orange', 'saengsan', 'M1200-08', NULL, '팁주기'),
  ('28350-2M110:3-04', '28350-2M110', 3, 4, '브레이징 조건 3회/1일 기록 + 계측기 교정', 'ITEM 조건관리 LIST 현행화 포함.', 'CP p050 (K6)', 'orange', 'saengsan', NULL, NULL, '브레이징 조건'),
  ('28350-2M110:3-05', '28350-2M110', 3, 5, '설비일상점검표·자주검사 C/SHEET 3개월 연속성', '', 'CP 전 공정 (K4·K5)', 'red', 'saengsan', 'L1100-07', NULL, '일상점검'),
  ('28350-2M110:3-06', '28350-2M110', 3, 6, '외주 관리 증빙: 대양금속(SQ O)·6개사 대장', '표면처리만 SQ 필수공정 논리 확정 + 외주 ISIR 접수대장·성적서 도래일 관리 신설.', '2권 p055', 'orange', 'gumae', 'K1200-01', NULL, '외주관리'),
  ('28350-2M110:4-01', '28350-2M110', 4, 1, '벤딩 작업자 인터뷰 리허설', '짧은/긴 마스터 왜 넣나? 금형 교체 후 첫 검사는?', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, '벤딩 마스터·금형'),
  ('28350-2M110:4-02', '28350-2M110', 4, 2, '용접·브레이징 작업자 인터뷰 리허설', '용접 8개소 누락 확인 방법, 브레이징 온도 이탈 시 조치.', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, '용접·브레이징'),
  ('28350-2M110:4-03', '28350-2M110', 4, 3, 'LEAK 작업자 인터뷰 리허설', '마스터 1회/일 시점, NG마스터 오검출 시 조치, 교정(굽힘수정)품 전수검사 규칙.', '추적맵 §6', 'orange', 'saengsan', NULL, NULL, 'LEAK 원점'),
  ('28350-2M110:4-04', '28350-2M110', 4, 4, '수입검사 담당 인터뷰 리허설', '대철정공·D.H ENG 입고 로트 추적, 불합격 통보 경로.', '추적맵 §3', 'orange', 'pumjil', 'L2100-07', NULL, '수입검사'),
  ('28350-2M110:4-05', '28350-2M110', 4, 5, '관리자 인터뷰: 품번 혼용 소명 스토리', '2M100/2M110 하위품번 공용 논리, EO 차이, IMDS 진행 상태를 관리자가 일관되게 답하도록.', '추적맵 §6', 'red', 'pumjil', NULL, NULL, '관리자');

-- ── 28350-2M100 (형제품번, 참고 트랙) ─────────────────────────
