  ('28350-2M100:1-01', '28350-2M100', 1, 1, '관리계획서 최신본 준비(방어 모범 세트)', '2권 p059~063 — 고객승인 서명 완비·개정 6건 정합·도금업체 변경 증빙체인 완결. 심사 서두 신뢰 형성에 활용.', '2권 p059~063', 'yellow', 'pumjil', 'J1102-03', NULL, '관리계획서'),
  ('28350-2M100:1-02', '28350-2M100', 1, 2, '제출서류 목록 대조·공정감사 평가표 상충 정리', '목록 20번 공정감사 평가표 X ↔ 4M 회신서 공정감사 필요 표시 — 상충 해소(실시 기록 확보 또는 사유서).', '2권 p001·p003', 'red', 'pumjil', NULL, NULL, '서류준비'),
  ('28350-2M100:2-01', '28350-2M100', 2, 1, 'IMDS 2017년판 갱신 확인', '2017.10.20 사내 송신 상태 + Il-Shin 명의 — 도금업체 변경(C2MPE167) 반영 여부 확인·재제출.', '2권 p050~054', 'red', 'gaebal', NULL, NULL, 'IMDS'),
  ('28350-2M100:2-02', '28350-2M100', 2, 2, '초도품보증서 서명·승인 공란 보완', '공급자 검토란 서명 누락 + 수요자 조립적합성 체크·승인번호 공란.', '2권 p005', 'red', 'pumjil', NULL, NULL, 'PSW'),
  ('28350-2M100:2-03', '28350-2M100', 2, 3, 'SQ 인증서 만료본 교체(2025.04.30 만료)', '갱신본 확보·교체.', '2권 p072', 'red', 'pumjil', NULL, NULL, '인증서'),
  ('28350-2M100:2-04', '28350-2M100', 2, 4, '염수분무 성적서 LOT 상이·n=1 정리', '용도 정기검사 발행분(LOT 24.06.04)을 ISIR(로트 24.08.05)에 인용 — 대표성 소명 또는 재시험.', '2권 p025', 'orange', 'pumjil', NULL, NULL, '성적서'),
  ('28350-2M100:2-05', '28350-2M100', 2, 5, '4M 날짜 역전 정리(의뢰 08.08 > 제출 08.07)', '4M 의뢰서 작성일이 ISIR 제출일보다 늦음 + 회신일자·발행번호 공란.', '2권 p001', 'orange', 'pumjil', NULL, NULL, '성적서'),
  ('28350-2M100:2-06', '28350-2M100', 2, 6, '검사구 검증 시효 갱신(JIG 2017·CMM 2022)', 'CMM 성적서 고객명 TSP 오기 포함 — 재검증 또는 유효성 평가서.', '2권 p055~058', 'orange', 'saengki', 'L1200-05', NULL, '검사구'),
  ('28350-2M100:3-01', '28350-2M100', 3, 1, 'LEAK 마스터·벤딩 MASTER 정비(2M110과 공용 라인)', '2M110 트랙과 동일 라인이면 결과 공유 — 이 항목은 라인 분리 시에만 별도 수행.', 'CP p062 (K7)', 'orange', 'saengsan', 'L2300-01', NULL, 'LEAK 원점'),
  ('28350-2M100:3-02', '28350-2M100', 3, 2, '특별특성 공정(LEAK) 공정능력 대체 논리 준비', 'CP상 공정능력 데이터 없음 — 전수검사+마스터 일일검증으로 대체하는 논리 문서화.', 'CP p063', 'orange', 'pumjil', 'L4102-02', NULL, '공정능력'),
  ('28350-2M100:3-03', '28350-2M100', 3, 3, '설비일상점검·자주검사 연속성(공용 라인 확인)', '', 'CP 전 공정 (K4·K5)', 'orange', 'saengsan', 'L1100-07', NULL, '일상점검'),
  ('28350-2M100:4-01', '28350-2M100', 4, 1, '교차 소환 대비: 2M110과 차이 즉답', '사양변경서(도금업체·색상 변경 C2MPE167) 기준으로 관리자·작업자 공통 답변 통일.', '2권 p004', 'orange', 'pumjil', NULL, NULL, '관리자');

